import{_ as i,a0 as t,w as o,s as r,ao as d,I as l,a1 as e,A as p,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"在 Linux 上用 DNS 实现简单的负载均衡 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上用 DNS 实现简单的负载均衡 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上用 DNS 实现简单的负载均衡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上用 DNS 实现简单的负载均衡 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180322 Simple Load Balancing with DNS on Linux","title":"在 Linux 上用 DNS 实现简单的负载均衡","tag":"201806","desc":""},"relativePath":"201806/20180322 Simple Load Balancing with DNS on Linux.md","filePath":"[post].md"}'),m={name:"201806/20180322 Simple Load Balancing with DNS on Linux.md"};function c(u,s,f,h,b,x){const n=t("Link");return o(),r("div",null,[s[18]||(s[18]=d(`<h1 id="在-linux-上用-dns-实现简单的负载均衡" tabindex="-1">在 Linux 上用 DNS 实现简单的负载均衡 <a class="header-anchor" href="#在-linux-上用-dns-实现简单的负载均衡" aria-label="Permalink to “在 Linux 上用 DNS 实现简单的负载均衡”">​</a></h1><blockquote><p>DNS 轮询将多个服务器映射到同一个主机名，并没有为这里展示的魔法做更多的工作。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/american-robin-920.jpg?itok=_B_RRbfj" alt=""></p><p>如果你的后端服务器是由多台服务器构成的，比如集群化或者镜像的 Web 或者文件服务器，通过负载均衡器提供了单一的入口点。业务繁忙的大型电商在高端负载均衡器上花费了大量的资金，用它来执行各种各样的任务：代理、缓存、状况检查、SSL 处理、可配置的优先级、流量整形等很多任务。</p><p>但是你并不需要做那么多工作的负载均衡器。你需要的是一个跨服务器分发负载的简单方法，它能够提供故障切换，并且不太在意它是否高效和完美。DNS 轮询和使用轮询的子域委派是实现这个目标的两种简单方法。</p><p>DNS 轮询是将多台服务器映射到同一个主机名上，当用户访问 <code>foo.example.com</code> 时多台服务器都可用于处理它们的请求，使用的就是这种方式。</p><p>当你有多个子域或者你的服务器在地理上比较分散时，使用轮询的子域委派就比较有用。你有一个主域名服务器，而子域有它们自己的域名服务器。你的主域名服务器将所有的到子域的请求指向到它们自己的域名服务器上。这将提升响应时间，因为 DNS 协议会自动查找最快的链路。</p><h3 id="dns-轮询" tabindex="-1">DNS 轮询 <a class="header-anchor" href="#dns-轮询" aria-label="Permalink to “DNS 轮询”">​</a></h3><p>轮询和<ruby>旅鸫鸟<rt>robins</rt></ruby>没有任何关系，据我相熟的图书管理员说，它最初是一个法语短语，<em>ruban rond</em>、或者 <em>round ribbon</em>。很久以前，法国政府官员以不分级的圆形、波浪线、或者直线形状来在请愿书上签字，以盖住原来的发起人。</p><p>DNS 轮询也是不分级的，简单配置一个服务器列表，然后将请求转到每个服务器上。它并不做真正的负载均衡，因为它根本就不测量负载，也没有状况检查，因此如果一个服务器宕机，请求仍然会发送到那个宕机的服务器上。它的优点就是简单。如果你有一个小的文件或者 Web 服务器集群，想通过一个简单的方法在它们之间分散负载，那么 DNS 轮询很适合你。</p><p>你所做的全部配置就是创建多条 A 或者 AAAA 记录，映射多台服务器到单个的主机名。这个 BIND 示例同时使用了 IPv4 和 IPv6 私有地址类：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fileserv.example.com. IN A 172.16.10.10</span></span>
<span class="line"><span>fileserv.example.com. IN A 172.16.10.11</span></span>
<span class="line"><span>fileserv.example.com. IN A 172.16.10.12</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fileserv.example.com. IN AAAA fd02:faea:f561:8fa0:1::10</span></span>
<span class="line"><span>fileserv.example.com. IN AAAA fd02:faea:f561:8fa0:1::11</span></span>
<span class="line"><span>fileserv.example.com. IN AAAA fd02:faea:f561:8fa0:1::12</span></span></code></pre></div><p>Dnsmasq 在 <code>/etc/hosts</code> 文件中保存 A 和 AAAA 记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>172.16.1.10 fileserv fileserv.example.com</span></span>
<span class="line"><span>172.16.1.11 fileserv fileserv.example.com</span></span>
<span class="line"><span>172.16.1.12 fileserv fileserv.example.com</span></span>
<span class="line"><span>fd02:faea:f561:8fa0:1::10 fileserv fileserv.example.com</span></span>
<span class="line"><span>fd02:faea:f561:8fa0:1::11 fileserv fileserv.example.com</span></span>
<span class="line"><span>fd02:faea:f561:8fa0:1::12 fileserv fileserv.example.com</span></span></code></pre></div><p>请注意这些示例都是很简化的，解析完全合格域名有多种方法，因此，关于如何配置 DNS 请自行学习。</p><p>使用 <code>dig</code> 命令去检查你的配置能否按预期工作。将 <code>ns.example.com</code> 替换为你的域名服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig @ns.example.com fileserv A fileserv AAA</span></span></code></pre></div><p>它将同时显示出 IPv4 和 IPv6 的轮询记录。</p><h3 id="子域委派和轮询" tabindex="-1">子域委派和轮询 <a class="header-anchor" href="#子域委派和轮询" aria-label="Permalink to “子域委派和轮询”">​</a></h3><p>子域委派结合轮询要做的配置会更多，但是这样有一些好处。当你有多个子域或者地理位置比较分散的服务器时，就应该去使用它。它的响应时间更快，并且宕机的服务器不会去响应，因此客户端不会因为等待回复而被挂住。一个短的 TTL，比如 60 秒，就能帮你做到。</p><p>这种方法需要多台域名服务器。在最简化的场景中，你需要一台主域名服务器和两个子域，每个子域都有它们自己的域名服务器。在子域服务器上配置你的轮询记录，然后在你的主域名服务器上配置委派。</p><p>在主域名服务器上的 BIND 中，你至少需要两个额外的配置，一个区声明以及在区数据文件中的 A/AAAA 记录。主域名服务器中的委派应该像如下的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ns1.sub.example.com. IN A 172.16.1.20</span></span>
<span class="line"><span>ns1.sub.example.com. IN AAAA fd02:faea:f561:8fa0:1::20</span></span>
<span class="line"><span>ns2.sub.example.com. IN A 172.16.1.21</span></span>
<span class="line"><span>ns2.sub.example.com. IN AAA fd02:faea:f561:8fa0:1::21</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sub.example.com. IN NS ns1.sub.example.com.</span></span>
<span class="line"><span>sub.example.com. IN NS ns2.sub.example.com.</span></span></code></pre></div><p>接下来的每台子域服务器上有它们自己的区文件。在这里它的关键点是每个服务器去返回它<strong>自己的</strong> IP 地址。在 <code>named.conf</code> 中的区声明，所有的服务上都是一样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zone &quot;sub.example.com&quot; {</span></span>
<span class="line"><span>    type master;</span></span>
<span class="line"><span>    file &quot;db.sub.example.com&quot;;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>然后数据文件也是相同的，除了那个 A/AAAA 记录使用的是各个服务器自己的 IP 地址。SOA 记录都指向到主域名服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; first subdomain name server</span></span>
<span class="line"><span>$ORIGIN sub.example.com.</span></span>
<span class="line"><span>$TTL 60</span></span>
<span class="line"><span>sub.example.com  IN SOA ns1.example.com. admin.example.com. (</span></span>
<span class="line"><span>        2018123456      ; serial</span></span>
<span class="line"><span>        3H              ; refresh</span></span>
<span class="line"><span>        15              ; retry</span></span>
<span class="line"><span>        3600000         ; expire</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sub.example.com. IN NS ns1.sub.example.com.</span></span>
<span class="line"><span>sub.example.com. IN A  172.16.1.20</span></span>
<span class="line"><span>ns1.sub.example.com.  IN AAAA  fd02:faea:f561:8fa0:1::20</span></span>
<span class="line"><span>; second subdomain name server</span></span>
<span class="line"><span>$ORIGIN sub.example.com.</span></span>
<span class="line"><span>$TTL 60</span></span>
<span class="line"><span>sub.example.com  IN SOA ns1.example.com. admin.example.com. (</span></span>
<span class="line"><span>        2018234567      ; serial</span></span>
<span class="line"><span>        3H              ; refresh</span></span>
<span class="line"><span>        15              ; retry</span></span>
<span class="line"><span>        3600000         ; expire</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sub.example.com. IN NS ns1.sub.example.com.</span></span>
<span class="line"><span>sub.example.com. IN A  172.16.1.21</span></span>
<span class="line"><span>ns2.sub.example.com.  IN AAAA  fd02:faea:f561:8fa0:1::21</span></span></code></pre></div><p>接下来生成子域服务器上的轮询记录，方法和前面一样。现在你已经有了多个域名服务器来处理到你的子域的请求。再说一次，BIND 是很复杂的，做同一件事情它有多种方法，因此，给你留的家庭作业是找出适合你使用的最佳配置方法。</p><p>在 Dnsmasq 中做子域委派很容易。在你的主域名服务器上的 <code>dnsmasq.conf</code> 文件中添加如下的行，去指向到子域的域名服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>server=/sub.example.com/172.16.1.20</span></span>
<span class="line"><span>server=/sub.example.com/172.16.1.21</span></span>
<span class="line"><span>server=/sub.example.com/fd02:faea:f561:8fa0:1::20</span></span>
<span class="line"><span>server=/sub.example.com/fd02:faea:f561:8fa0:1::21</span></span></code></pre></div><p>然后在子域的域名服务器上的 <code>/etc/hosts</code> 中配置轮询。</p><p>获取配置方法的详细内容和帮助，请参考这些资源：</p>`,32)),l("ul",null,[l("li",null,[e(n,{href:"http://www.thekelleys.org.uk/dnsmasq/doc.html"},{default:p(()=>[...s[0]||(s[0]=[a("Dnsmasq",-1)])]),_:1})]),l("li",null,[e(n,{href:"http://shop.oreilly.com/product/9780596100575.do"},{default:p(()=>[...s[1]||(s[1]=[a("DNS and BIND, 5th Edition",-1)])]),_:1})])]),l("p",null,[s[3]||(s[3]=a("通过来自 Linux 基金会和 edX 的免费课程 ",-1)),e(n,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:p(()=>[...s[2]||(s[2]=[a('"Linux 入门" ',-1)])]),_:1}),s[4]||(s[4]=a(" 学习更多 Linux 的知识。",-1))]),s[19]||(s[19]=l("hr",null,null,-1)),l("p",null,[s[6]||(s[6]=a("via: ",-1)),e(n,{href:"https://www.linux.com/learn/intro-to-linux/2018/3/simple-load-balancing-dns-linux"},{default:p(()=>[...s[5]||(s[5]=[a("https://www.linux.com/learn/intro-to-linux/2018/3/simple-load-balancing-dns-linux",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=a("作者：",-1)),e(n,{href:"https://www.linux.com/users/cschroder"},{default:p(()=>[...s[7]||(s[7]=[a("CARLA SCHRODER",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),e(n,{href:"https://github.com/qhwdw"},{default:p(()=>[...s[8]||(s[8]=[a("qhwdw",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const N=i(m,[["render",c]]);export{A as __pageData,N as default};
